PRAGMA foreign_keys=ON;
CREATE TABLE source_documents(id TEXT PRIMARY KEY,publisher TEXT NOT NULL,title TEXT NOT NULL,url TEXT NOT NULL,accessed_at TEXT NOT NULL,sha256 TEXT,reference_year INTEGER,license TEXT);
CREATE TABLE elections(id TEXT PRIMARY KEY,year INTEGER NOT NULL,kind TEXT NOT NULL CHECK(kind IN('assembly','parliament')),source_id TEXT REFERENCES source_documents);
CREATE TABLE districts(id TEXT PRIMARY KEY,name TEXT NOT NULL,reference_year INTEGER NOT NULL);
CREATE TABLE constituencies(id INTEGER PRIMARY KEY CHECK(id BETWEEN 1 AND 60),name TEXT NOT NULL,reservation TEXT CHECK(reservation IN('GEN','SC','ST')));
CREATE TABLE constituency_districts(ac_id INTEGER REFERENCES constituencies,district_id TEXT REFERENCES districts,valid_from INTEGER,valid_to INTEGER,source_id TEXT REFERENCES source_documents,PRIMARY KEY(ac_id,district_id,valid_from));
CREATE TABLE candidates(id TEXT PRIMARY KEY,display_name TEXT NOT NULL,identity_status TEXT NOT NULL CHECK(identity_status IN('reviewed','unresolved')),review_note TEXT);
CREATE TABLE parties(id TEXT PRIMARY KEY,name TEXT NOT NULL,color TEXT NOT NULL);
CREATE TABLE candidacies(id TEXT PRIMARY KEY,election_id TEXT REFERENCES elections,ac_id INTEGER REFERENCES constituencies,candidate_id TEXT REFERENCES candidates,source_name TEXT NOT NULL,party_id TEXT REFERENCES parties,source_id TEXT NOT NULL REFERENCES source_documents,source_page INTEGER,UNIQUE(election_id,ac_id,candidate_id));
CREATE INDEX candidacy_search ON candidacies(election_id,ac_id,party_id);
CREATE TABLE results(candidacy_id TEXT PRIMARY KEY REFERENCES candidacies,votes INTEGER CHECK(votes>=0),rank INTEGER CHECK(rank>0),verification_status TEXT NOT NULL,source_id TEXT NOT NULL REFERENCES source_documents);
CREATE TABLE turnout(election_id TEXT REFERENCES elections,ac_id INTEGER REFERENCES constituencies,electors INTEGER,votes_polled INTEGER,valid_votes INTEGER,nota INTEGER,rejected INTEGER,source_id TEXT NOT NULL REFERENCES source_documents,PRIMARY KEY(election_id,ac_id));
CREATE TABLE candidate_affidavits(id TEXT PRIMARY KEY,candidate_id TEXT REFERENCES candidates,election_id TEXT REFERENCES elections,assets_inr INTEGER,liabilities_inr INTEGER,age INTEGER,education TEXT,occupation TEXT,declared_cases INTEGER,legal_status_note TEXT,source_id TEXT NOT NULL REFERENCES source_documents,verification_status TEXT NOT NULL);
CREATE TABLE candidate_party_history(id TEXT PRIMARY KEY,candidate_id TEXT REFERENCES candidates,party_id TEXT REFERENCES parties,effective_date TEXT,source_id TEXT NOT NULL REFERENCES source_documents);
CREATE TABLE socioeconomic_indicators(id TEXT PRIMARY KEY,name TEXT NOT NULL,unit TEXT NOT NULL,value REAL,reference_year INTEGER NOT NULL,geography_id TEXT NOT NULL,geography_version TEXT NOT NULL,estimate_status TEXT,source_id TEXT NOT NULL REFERENCES source_documents);
CREATE TABLE geographic_boundaries(id TEXT PRIMARY KEY,ac_id INTEGER REFERENCES constituencies,reference_year INTEGER,status TEXT NOT NULL,license TEXT NOT NULL,source_id TEXT NOT NULL REFERENCES source_documents);
CREATE TABLE political_events(id TEXT PRIMARY KEY,event_date TEXT NOT NULL,title TEXT NOT NULL,description TEXT NOT NULL,location TEXT,evidence_class TEXT NOT NULL,verification_status TEXT NOT NULL,source_id TEXT NOT NULL REFERENCES source_documents);
CREATE TABLE source_claims(id TEXT PRIMARY KEY,claim TEXT NOT NULL,source_id TEXT NOT NULL REFERENCES source_documents,page_locator TEXT,status TEXT NOT NULL);
CREATE TABLE research_notes(id TEXT PRIMARY KEY,topic TEXT NOT NULL,body TEXT NOT NULL,evidence_class TEXT NOT NULL,source_id TEXT REFERENCES source_documents);
